"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[2013],{55777:e=>{e.exports=JSON.parse('{"functions":[{"name":"Rate","desc":"Lateral drift rate in **1/s**, an acceleration *per unit speed*: the applied\\nacceleration is `value * speed`. Drift scales with velocity, so lateral displacement\\ngrows superlinearly with time of flight.\\n\\nTypical values are small, on the order of `1e-3`. Setting this enables drift.\\n\\nDefault: `nil` (disabled)","params":[{"name":"value","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"GyroDriftBuilder"}],"function_type":"method","source":{"line":791,"path":"docs/SubBuilders.lua"}},{"name":"Axis","desc":"Reference axis for drift direction. `nil` = world UP (right-hand rifling).\\n\\nDefault: `nil`","params":[{"name":"value","desc":"","lua_type":"Vector3"}],"returns":[{"desc":"","lua_type":"GyroDriftBuilder"}],"function_type":"method","source":{"line":801,"path":"docs/SubBuilders.lua"}},{"name":"Done","desc":"Returns the root [BehaviorBuilder].","params":[],"returns":[{"desc":"","lua_type":"BehaviorBuilder"}],"function_type":"method","source":{"line":807,"path":"docs/SubBuilders.lua"}}],"properties":[],"types":[],"name":"GyroDriftBuilder","desc":"Sub-builder for gyroscopic drift. Opened via [BehaviorBuilder:GyroDrift].\\nCall `:Done()` to return to the root [BehaviorBuilder].","source":{"line":777,"path":"docs/SubBuilders.lua"}}')}}]);